310	func brainSessionsFingerprint(outputDir string) string {
311		manifest, err := loadBrainManifest(outputDir)
312		if err != nil || manifest.Sources == nil || manifest.Sources.Sessions == nil {
313			return ""
314		}
315		return sessionSourceFingerprint(manifest.Sources.Sessions)
