588	func extractToolResultFacts(text string) []historyFragment {
589		text = strings.TrimSpace(text)
590		if text == "" || !historyTextHasCodeFactSignal(text) {
591			return nil
592		}
593		lines := strings.Split(text, "\n")
594		seen := map[string]struct{}{}
595		var fragments []historyFragment
596		lastEnd := -1
597		for i, line := range lines {
598			if i < lastEnd {
599				continue
600			}
601			if !historyLineHasCodeFactSignal(line) {
602				continue
603			}
604			start := max(0, i-2)
605			end := min(len(lines), i+4)
606			snippet := cleanHistoryCodeFactSnippet(cleanHistorySummary(strings.Join(lines[start:end], " ")))
607			if snippet == "" {
608				continue
609			}
610			if _, ok := seen[snippet]; ok {
611				continue
612			}
613			seen[snippet] = struct{}{}
614			fragments = append(fragments, historyFragment{Text: snippet, Source: "tool_result_fact"})
615			lastEnd = end
616			if len(fragments) >= 8 {
617				break
618			}
619		}
620		return fragments
621	}
